#include <stdio.h>
#include <stdlib.h>
#include <limits.h>
#include <string.h>

int main(int argc, char **argv) {
    if (argc < 3) {
        puts("NO_INPUT");
        return 0;
    }
    char *end1, *end2;
    long num = strtol(argv[1], &end1, 10);
    long den = strtol(argv[2], &end2, 10);
    if (*end1 != '\0' || *end2 != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    if (llabs(num) > 100000) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    if (den == 0) {
        puts("[]");
        return 0;
    }
    long terms[200];
    int count = 0;
    long n = num, d = den;
    while (d != 0) {
        if (count >= 200) {
            puts("ERROR");
            return 0;
        }
        long q = n / d;
        long r = n % d;
        // Adjust for floor division to keep remainder non‑negative
        if (r < 0) {
            if (d > 0) {
                q -= 1;
                r += d;
            } else {
                q += 1;
                r -= d;
            }
        }
        terms[count++] = q;
        n = d;
        d = r;
    }
    putchar('[');
    for (int i = 0; i < count; ++i) {
        if (i > 0) {
            if (i == count - 1)
                printf("; ");
            else
                printf(", ");
        }
        printf("%ld", terms[i]);
    }
    putchar(']');
    putchar('\n');
    return 0;
}
